add('memory-grid','Memory Grid','Game','Match eight pairs in sixteen shuffled cards.','<button id="reset">New game</button><div id="board" class="grid" style="grid-template-columns:repeat(4,1fr)"></div>'+out,"let deck,open=[],matched=new Set(),moves=0,locked=false,version=0;const render=()=>{$('#board').replaceChildren(...deck.map((v,i)=>{const b=document.createElement('button');b.textContent=matched.has(i)||open.includes(i)?v:'?';b.style.minHeight='70px';b.setAttribute('aria-label','Card '+(i+1));b.disabled=matched.has(i)||locked;b.onclick=()=>{if(open.includes(i))return;open.push(i);render();if(open.length===2){moves++;const [a,b]=open;if(deck[a]===deck[b]){matched.add(a);matched.add(b);open=[];render();}else{locked=true;render();const current=version;setTimeout(()=>{if(current!==version)return;open=[];locked=false;render();},750);}}};return b;}));show(matched.size===16?'Complete in '+moves+' moves!':'Moves: '+moves+' · Pairs: '+matched.size/2);};$('#reset').onclick=()=>{version++;deck=[...'ABCDEFGHABCDEFGH'];for(let i=deck.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[deck[i],deck[j]]=[deck[j],deck[i]];}open=[];matched=new Set();moves=0;locked=false;render();};$('#reset').click();")
add('sort-stage','Sort Stage','Algorithms','Watch insertion sort arrange a shuffled set of bars.','<button id="shuffle">Shuffle</button><button id="go">Sort</button><canvas width="800" height="360"></canvas>'+out,"const ctx=$('canvas').getContext('2d');let a=[],i=1,j=1,running=false,moves=0;const draw=()=>{ctx.clearRect(0,0,800,360);a.forEach((v,k)=>{ctx.fillStyle=k===j?'#fb923c':'#a9f575';ctx.fillRect(k*20+2,360-v*8,16,v*8);});show('Comparisons: '+moves);};$('#shuffle').onclick=()=>{running=false;a=Array.from({length:40},(_,i)=>i+1);for(let k=39;k>0;k--){const n=Math.floor(Math.random()*(k+1));[a[k],a[n]]=[a[n],a[k]];}i=j=1;moves=0;draw();};$('#go').onclick=()=>running=true;setInterval(()=>{if(!running)return;if(i>=a.length){running=false;show('Sorted · '+moves+' comparisons');return;}moves++;if(j>0&&a[j]<a[j-1]){[a[j],a[j-1]]=[a[j-1],a[j]];j--;}else{i++;j=i;}draw();},35);$('#shuffle').click();")
add('fractal-window','Fractal Window','Art','Explore a Mandelbrot set; click to zoom and reset to return.','<button id="reset">Reset</button><canvas width="600" height="400"></canvas>'+out,"const c=$('canvas'),ctx=c.getContext('2d');let cx=-.5,cy=0,scale=3.4;const draw=()=>{const img=ctx.createImageData(600,400);for(let y=0;y<400;y++)for(let x=0;x<600;x++){const a=cx+(x/600-.5)*scale,b=cy+(y/400-.5)*scale*2/3;let zx=0,zy=0,n=0;while(zx*zx+zy*zy<4&&n<100){const t=zx*zx-zy*zy+a;zy=2*zx*zy+b;zx=t;n++;}const k=(y*600+x)*4;img.data[k]=n===100?10:n*9%256;img.data[k+1]=n===100?15:n*5%256;img.data[k+2]=n===100?25:160+n%96;img.data[k+3]=255;}ctx.putImageData(img,0,0);show('Span: '+scale.toPrecision(4)+' · 100 iterations');};c.onclick=e=>{if(scale<1e-12)return;const r=c.getBoundingClientRect();cx+=((e.clientX-r.left)/r.width-.5)*scale;cy+=((e.clientY-r.top)/r.height-.5)*scale*2/3;scale*=.5;draw();};$('#reset').onclick=()=>{cx=-.5;cy=0;scale=3.4;draw();};draw();")
add('particle-atlas','Particle Atlas','Simulation','Move the pointer to attract particles; pause to inspect.','<button id="pause">Pause / Resume</button><canvas width="800" height="450"></canvas>',"const c=$('canvas'),ctx=c.getContext('2d');let active=true,target={x:400,y:225};const points=Array.from({length:140},()=>({x:Math.random()*800,y:Math.random()*450,vx:0,vy:0}));c.onpointermove=e=>{const r=c.getBoundingClientRect();target={x:(e.clientX-r.left)/r.width*800,y:(e.clientY-r.top)/r.height*450};};$('#pause').onclick=()=>active=!active;const frame=()=>{if(active){ctx.fillStyle='rgba(16,22,36,.18)';ctx.fillRect(0,0,800,450);for(const p of points){const dx=target.x-p.x,dy=target.y-p.y,d=Math.max(100,dx*dx+dy*dy);p.vx=(p.vx+dx/d*4)*.99;p.vy=(p.vy+dy/d*4)*.99;p.x=(p.x+p.vx+800)%800;p.y=(p.y+p.vy+450)%450;ctx.fillStyle='#a9f575';ctx.fillRect(p.x,p.y,2,2);}}requestAnimationFrame(frame);};frame();")
add('beat-box','Beat Box','Music','A four-voice, sixteen-step drum sequencer using synthesized sounds.','<label>Tempo<input id="bpm" type="number" min="40" max="240" value="110"></label><button id="toggle">Play / Stop</button><div id="board" style="overflow-x:auto"></div>'+out,"let audio,timer,step=0;const pattern=Array.from({length:4},()=>Array(16).fill(false));const board=$('#board');for(let r=0;r<4;r++){const row=document.createElement('div');row.style.whiteSpace='nowrap';for(let s=0;s<16;s++){const b=document.createElement('button');b.textContent='·';b.style.padding='8px';b.setAttribute('aria-label','Voice '+(r+1)+' step '+(s+1));b.onclick=()=>{pattern[r][s]=!pattern[r][s];b.textContent=pattern[r][s]?'●':'·';};row.append(b);}board.append(row);}const tick=()=>{show('Step '+(step+1));pattern.forEach((row,r)=>{if(row[step]){const o=audio.createOscillator(),g=audio.createGain(),t=audio.currentTime;o.type=r===3?'square':'sine';o.frequency.setValueAtTime([110,220,440,880][r],t);o.frequency.exponentialRampToValueAtTime([40,80,180,400][r],t+.12);g.gain.setValueAtTime(.15,t);g.gain.exponentialRampToValueAtTime(.001,t+.15);o.connect(g).connect(audio.destination);o.start(t);o.stop(t+.16);}});step=(step+1)%16;timer=setTimeout(tick,60000/Math.min(240,Math.max(40,Number($('#bpm').value)||110))/4);};$('#toggle').onclick=async()=>{if(timer){clearTimeout(timer);timer=null;show('Stopped');}else{audio??=new AudioContext();await audio.resume();tick();}};")
add('metronome','Metronome','Music','Simple audible beats and a visual pulse.','<label>BPM<input id="bpm" type="number" min="30" max="240" value="100"></label><button id="toggle">Play / Stop</button><div class="big" id="beat">♩</div>'+out,"let audio,timer,count=0;const tick=()=>{count=count%4+1;$('#beat').textContent=count;const t=audio.currentTime,o=audio.createOscillator(),g=audio.createGain();o.frequency.value=count===1?1000:650;g.gain.setValueAtTime(.15,t);g.gain.exponentialRampToValueAtTime(.001,t+.06);o.connect(g).connect(audio.destination);o.start(t);o.stop(t+.07);timer=setTimeout(tick,60000/Math.min(240,Math.max(30,Number($('#bpm').value)||100)));};$('#toggle').onclick=async()=>{if(timer){clearTimeout(timer);timer=null;show('Stopped');}else{audio??=new AudioContext();await audio.resume();tick();show('Playing');}};")
add('local-notes','Local Notes','Productivity','A plain text scratchpad saved in this browser, with file export.',text+'<button id="save">Download text</button>'+out,"try{$('#input').value=localStorage.getItem('pocket-notes')||'';}catch{}$('#input').oninput=()=>{try{localStorage.setItem('pocket-notes',$('#input').value);show('Saved in this browser');}catch{show('Storage unavailable. Download to keep a copy.');}};$('#save').onclick=()=>{const a=document.createElement('a'),u=URL.createObjectURL(new Blob([$('#input').value],{type:'text/plain;charset=utf-8'}));a.href=u;a.download='notes.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};")
add('unit-station','Unit Station','Utility','Convert distance, mass and temperature units.','<label>Value<input id="n" type="number" value="1" step="any"></label><label>Conversion<select id="mode"><option value="km">Kilometers → miles</option><option value="mi">Miles → kilometers</option><option value="kg">Kilograms → pounds</option><option value="lb">Pounds → kilograms</option><option value="c">Celsius → Fahrenheit</option><option value="f">Fahrenheit → Celsius</option></select></label>'+out,"const run=()=>{const n=Number($('#n').value);const f={km:n/1.609344,mi:n*1.609344,kg:n/0.45359237,lb:n*0.45359237,c:n*1.8+32,f:(n-32)/1.8};show(f[$('#mode').value]);};$('#n').oninput=$('#mode').onchange=run;run();")
add('aspect-desk','Aspect Desk','Design','Find a matching image dimension for a selected aspect ratio.','<label>Width<input id="width" type="number" min="1" value="1920"></label><label>Aspect<select id="ratio"><option value="1.7777777777777777">16:9</option><option value="1.3333333333333333">4:3</option><option value="1">1:1</option><option value="0.5625">9:16</option><option value="2.3333333333333335">21:9</option></select></label>'+out,"const run=()=>{const w=Number($('#width').value);if(!Number.isFinite(w)||w<=0)return show('Enter a positive width');show({width:w,height:Math.round(w/Number($('#ratio').value))});};$('#width').oninput=$('#ratio').onchange=run;run();")
add('binary-desk','Binary Desk','Developer','Convert arbitrary-size integers between decimal, hexadecimal and binary.','<label>Integer<input id="n" value="255"></label><label>Input base<select id="base"><option value="10">Decimal</option><option value="16">Hexadecimal (unsigned)</option><option value="2">Binary (unsigned)</option></select></label><button id="go">Convert</button>'+out,"$('#go').onclick=()=>safe(()=>{const s=$('#n').value.trim(),b=$('#base').value;if(!(b==='10'?/^-?\d+$/:b==='16'?/^[0-9a-f]+$/i:/^[01]+$/).test(s))throw Error('Invalid integer for selected base');const n=BigInt((b==='16'?'0x':b==='2'?'0b':'')+s);show({decimal:n.toString(10),hexadecimal:n.toString(16),binary:n.toString(2)});});$('#go').click();")
